const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Call `operation` until it resolves.
 *
 * Failed attempts are followed by an exponentially growing delay
 * (`baseDelayMs * 2 ** (attempt - 1)`, capped at `maxDelayMs`) so a failing
 * dependency isn't hammered with immediate retries.
 */
export async function retry(operation, options = {}) {
  const maxAttempts = options.maxAttempts ?? 3;
  const baseDelayMs = options.baseDelayMs ?? 100;
  const maxDelayMs = options.maxDelayMs ?? 2000;
  const sleep = options.sleep ?? defaultSleep;
  let last;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await operation(attempt);
    } catch (error) {
      last = error;
      if (attempt < maxAttempts) {
        const delay = Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs);
        await sleep(delay);
      }
    }
  }
  throw new RetriesExhausted(maxAttempts, last);
}

