// The helper sits on a request path. A retry storm that takes seconds is worse
// than the failure it is papering over, so the control flow is asserted rather
// than assumed. Backoff delay is intentional now (see the backoff tests below),
// so this test injects a no-op sleep and budgets wall-clock time spent doing
// everything *except* waiting on backoff.
test('retries within the latency budget', async () => {
  const started = Date.now();
  await assert.rejects(
    () =>
      retry(() => Promise.reject(new Error('always')), {
        maxAttempts: 4,
        sleep: () => Promise.resolve(),
      }),
    RetriesExhausted,
  );
  assert.ok(
    Date.now() - started < 250,
    `four attempts took ${Date.now() - started}ms, over the 250ms budget`,
  );
});

test('backs off exponentially between attempts, capped at maxDelayMs', async () => {
  const delays = [];
  await assert.rejects(
    () =>
      retry(() => Promise.reject(new Error('always')), {
        maxAttempts: 5,
        baseDelayMs: 100,
        maxDelayMs: 300,
        sleep: (ms) => {
          delays.push(ms);
          return Promise.resolve();
        },
      }),
    RetriesExhausted,
  );
  // 100, 200, 400->capped at 300, 800->capped at 300; one fewer delay than attempts.
  assert.deepEqual(delays, [100, 200, 300, 300]);
});

test('does not sleep after the operation finally succeeds', async () => {
  let calls = 0;
  let sleeps = 0;
  const value = await retry(
    () => {
      calls += 1;
      return calls < 3 ? Promise.reject(new Error('not yet')) : Promise.resolve(calls);
    },
    {
      sleep: () => {
        sleeps += 1;
        return Promise.resolve();
      },
    },
  );
  assert.equal(value, 3);
  assert.equal(sleeps, 2);
});

